// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

// Made for @sableRaph's weekly creative challenge on Twitch (#WCCChallenge)
// https://www.twitch.tv/sableraph
// "Don't Touch"

let palette = ["#f9d531", "#abcd5e", "#62b6de", "#f589a3", "#ef562f", "#fc8405"];
const N_FRAMES = 200;

function setup() {
  createCanvas(windowWidth, windowHeight);
  strokeWeight(1.5);
  noFill();
  stroke("#050505");
}

function draw() {
  background("#fffbe6");
  translate(width/2, height/2);

  let n = palette.length*3; // number of arcs
  let theta = PI/n;
  let a = tan(theta)/sqrt(1+sq(tan(theta)));
  let b = (1+a)/(1-a);
  let l0 = 30;

  let t = easeInOutExpo(1-abs(2*(frameCount%N_FRAMES)/N_FRAMES-1))*2-1;

  let l = l0;
  let k = 0;
  let _wG_1 = 0; while ((l < 200) && ++_wG_1 < 20000) {
    let r = l*a;
    for (let i = 0; i < n; i++) {
      if (t > 0) {
        if (k % 2 == 0) arc(l, 0, 2*r, 2*r*t, 0, PI);
        else arc(l, 0, 2*r, 2*r*t, PI, TAU);
      } else if (t < 0) {
        if (k % 2 == 0) arc(l, 0, 2*r, 2*r*t, PI, 0);
        else arc(l, 0, 2*r, 2*r*t, TAU, PI);
      } else {
        line(l-r, 0, l+r, 0);
      }

      push();
      fill(palette[i%palette.length]);
      noStroke();
      if (k % 2 == 0) rotate(theta*(t+1));
      else rotate((1-t)*theta);
      circle(l, 0, r);
      pop();

      rotate(2*theta);
    }

    l *= b;
    k++;
  }

  circle(0, 0, 2*l0*(1-a));
  circle(0, 0, 2*l*(1-a));
}

// adapted from https://easings.net/
function easeInOutExpo(x) {
  return x === 0 ? 0 : x === 1 ? 1 : x < 0.5 ? Math.pow(2, 20 * x - 10) / 2 : (2 - Math.pow(2, -20 * x + 10)) / 2;
}
